<!--vbase-->
<template>
  <div class="full-width dashboard-list-area">
    <div class="">
      <div class="row q-gutter-md">
        <template v-for="column in columns" :key="column.title">
          <div
            class="highlighted-back rounded-lg px-3 py-3 column-width rounded relative-position"
          >
            <p class="text-weight-bold text-lg">
              {{ $t(column.title) }}
            </p>
            <!-- This element is the only scroll container of the column: the
                 scroll event does not bubble, so the listener has to sit on it. -->
            <div
              class="height-100vh-260px"
              :data-column="column.title"
              @scroll.passive="handleScroll($event, column)"
            >
              <!-- Draggable component comes from vuedraggable. It provides drag & drop functionality -->
              <draggable
                :list="column.tasks"
                group="tasks"
                ghost-class="ghost-card"
                @change="dragEnd"
                @end="resetError"
                :move="checkMove"
                :animation="200"
                class="column-drop-area"
              >
                <task-card
                  v-for="task in column.tasks.slice(0, column.visibleCount)"
                  :key="task.id"
                  :task="task"
                  @deleteRecord="deleteRecord"
                  @documentClick="routeByStatus"
                  @cardClick="cardClick"
                  @updateStatusTaskClick="bulkUpdateStatusTasks"
                  class="q-mt-sm cursor-move"
                />
              </draggable>
            </div>

            <div v-if="column.loadingMoreTasks" class="column-loader">
              <q-spinner-dots color="primary" size="24px" />
            </div>
          </div>
        </template>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperUtil from 'src/utils/helperUtil';
import { taskApiService } from 'src/services';
import { useTaskStore } from 'src/store/main';
import type { ColumnWithExtras } from 'src/store/Document/tasks.store';
import helperMixin from 'src/mixins/helperMixin';
import documentUtil from 'src/utils/documentUtil';
import { ApiExceptions } from 'src/exceptions/index';
import { VueDraggableNext } from 'vue-draggable-next';
import dragDropColumn from 'src/mixins/dragDropColumn';
import TaskCard from 'src/pages/Tasks/Board/taskCard.vue';
import { isUserAdmin } from 'src/utils/UserDetails';

// Upper bound for the "keep loading until the column can scroll" loop.
const MAX_FILL_ATTEMPTS = 5;

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, helperUtil, documentUtil, dragDropColumn],
  components: {
    draggable: VueDraggableNext,
    TaskCard,
  },
  emits: ['routeByStatus', 'deleteRecord', 'bulkUpdateStatusTasks'],
  data() {
    return {
      errorShown: false,
      InvoicesClearInterval: 0 as any,
      debounceSearchInputFunc: {} as any,
    };
  },

  methods: {
    checkMove(event: any) {
      const task = event.draggedContext.element;

      if (this.isHasAccess(task)) {
        if (!this.errorShown) {
          // Show error only if not shown before
          notify.error(this.$t('task_permission_error_for_non_admin'));
          this.errorShown = true; // Set flag to prevent multiple errors
        }
        return false;
      }
    },
    resetError() {
      this.errorShown = false;
    },

    dragEnd(event: any, lst: any) {
      this.errorShown = false;
      if (!event.added) {
        return;
      }
      const task_id = event.added.element.id;
      const current_task = event.added.element;
      let new_status = '';
      this.columns.forEach((column: any) => {
        column.tasks.forEach((task: any) => {
          if (task.id === task_id) {
            new_status = column.title;
          }
        });
      });
      this.updateTaskStatus(current_task, new_status);
    },

    async updateTaskStatus(task: any, new_status: any) {
      try {
        if (!task) {
          return;
        }
        task.status = new_status;
        if (task.deadline) {
          task.deadline = new Date(task.deadline).toISOString();
        }
        const response: any = await taskApiService.editTask(task.id, task);
        if (response.success === false) {
          throw response;
        }

        const event = new CustomEvent('refresh_view', {
          detail: { show_shimmer_loader: true },
        });
        document.dispatchEvent(event);

        notify.success(this.$t('status_updated_successfully'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    cardClick(row: dynamicObj) {
      const id = String(row.id);
      this.$router.push({
        path: `/task/${id}`,
      });
    },
    deleteRecord(task: any) {
      this.$emit('deleteRecord', task.id);
    },
    routeByStatus(row: dynamicObj) {
      this.$emit('routeByStatus', row, true);
    },
    bulkUpdateStatusTasks(task: any, status: string) {
      if (!isUserAdmin() && this.isHasAccess(task)) {
        notify.error(this.$t('task_permission_error_for_non_admin'));
        return;
      }
      this.$emit('bulkUpdateStatusTasks', [task.id], status);
    },
    handleScroll(event: any, column: ColumnWithExtras) {
      const el = event.target as HTMLElement;
      const near_bottom =
        el.scrollTop + el.clientHeight >= el.scrollHeight - 50;
      if (near_bottom) {
        void this.showMoreColumnTasks(column);
      }
    },

    /**
     * A column that does not overflow can never fire a scroll event, so it
     * would stay stuck on whatever the shared page happened to contain —
     * including staying empty while the server does have records for its
     * status. Load pages until the column can scroll or the status is drained.
     */
    async fillColumn(column: ColumnWithExtras) {
      for (let attempt = 0; attempt < MAX_FILL_ATTEMPTS; attempt++) {
        const el = this.$el?.querySelector(`[data-column="${column.title}"]`);
        // Not measurable (not rendered / hidden) or already scrollable — leave
        // it to the scroll handler instead of firing requests blindly.
        if (
          !el ||
          el.clientHeight === 0 ||
          el.scrollHeight > el.clientHeight + 4
        ) {
          return;
        }
        if (!(await this.showMoreColumnTasks(column))) {
          return;
        }
        await this.$nextTick();
      }
    },

    async fillColumns() {
      await this.$nextTick();
      await Promise.all(
        this.columns.map((column: ColumnWithExtras) => this.fillColumn(column)),
      );
    },
  },

  mounted() {
    void this.fillColumns();
  },

  watch: {
    // Every refresh re-splits the shared page over the columns, which can leave
    // a column empty or too short to scroll — top them up once that is done.
    board_revision() {
      void this.fillColumns();
    },
  },

  setup() {
    const task_store = useTaskStore();
    const { columns, userGroupIds, board_revision } = storeToRefs(task_store);
    const { isHasAccess, showMoreColumnTasks } = task_store;

    return {
      columns,
      userGroupIds,
      board_revision,
      isHasAccess,
      showMoreColumnTasks,
    };
  },
});
</script>

