<template>
  <q-select
    class="q-mr-sm"
    dense
    style="width: 227px"
    outlined
    :options="priorityOptions"
    v-model="selected_value"
    @update:model-value="
      (val: any) => {
        valueUpdated(val);
      }
    "
    :label="$t('priority')"
  />
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useTaskStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { isUndefinedOrNull } from 'src/utils/general';
import { priority_list } from 'src/constants/enum';
import type { dynamicObj } from 'src/pages/assets';

export default defineComponent({
  mixins: [],
  props: {},
  watch: {
    taskfiltersMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadSavedFiler();
      },
    },
  },
  data() {
    return {};
  },
  mounted() {
    this.priorityOptions = priority_list.map((item: any) => {
      return {
        label: this.$t(item),
        value: item,
      };
    });
    this.loadSavedFiler();
  },
  unmounted: function () {
    // unmounted
  },

  methods: {
    loadSavedFiler() {
      const status = this.taskfiltersMap.get('priority');
      if (!status) {
        this.selected_value = '';
        return;
      }

      this.selected_value = status;
    },

    valueUpdated(val: any) {
      this.selected_value = val;
      if (this.handleEmptyValue()) {
        return;
      }

      this.setItemInFiltersMap('priority', this.selected_value);
      this.triggerApplyFilters();
    },

    handleEmptyValue() {
      if (
        this.selected_value === '' ||
        isUndefinedOrNull(this.selected_value)
      ) {
        this.deleteItemInFiltersMap('priority');
        this.triggerApplyFilters();
        return true;
      }
      return false;
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },
  },
  setup() {
    const task_store = useTaskStore();
    const { taskfiltersMap } = storeToRefs(task_store);
    const { setItemInFiltersMap, deleteItemInFiltersMap } = task_store;

    return {
      selected_value: ref(''),
      priorityOptions: ref([] as dynamicObj[]),
      taskfiltersMap,

      setItemInFiltersMap,
      deleteItemInFiltersMap,
    };
  },
});
</script>
<style lang="scss"></style>
