<template>
  <div class="full-width q-pa-md text-grey-8">
    <template v-for="(row, row_index) in tasks" :key="row_index">
      <template v-for="(columnInfo, index) in table_columns" :key="index">
        <template v-if="columnInfo.name === 'title'">
          <div class="row">
            <div class="col-11">
              <div
                class="text-primary ellipsify"
                @click="$emit('rowClick', columnInfo.name, row)"
              >
                {{ row[columnInfo.name] }}
              </div>
            </div>

            <div class="col-1">
              <q-icon
                name="expand_more"
                size="md"
                :id="'expand_more_' + row['id']"
                @click="expand(row['id'])"
              />
              <q-icon
                name="expand_less"
                size="md"
                class="hidden"
                :id="'expand_less_' + row['id']"
                @click="expand(row['id'])"
              />
            </div>
          </div>
        </template>
        <template v-else>
          <div
            class="row"
            :class="columnInfo.hidden ? ' hidden mark_hidden_' + row['id'] : ''"
          >
            <div class="col-4">
              <template v-if="columnInfo.hasOwnProperty('label')">
                <span class="q-pr-md">{{ $t(columnInfo.label) }}</span>
              </template>
              <template v-else>
                {{ getLabelTranslation(columnInfo.translation_key) }}
              </template>
            </div>
            <div class="col-8">
              {{ row[columnInfo.name] ? row[columnInfo.name] : '-' }}
            </div>
          </div>
        </template>
      </template>
      <div class="full-width border-bottom q-mt-sm q-mb-sm"></div>
    </template>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useTaskStore } from 'src/store/main';
import documentUtil from 'src/utils/documentUtil';
import { mobile_table_columns } from 'src/pages/Tasks/List/table_columns.js';
import type { dynamicObj } from 'src/pages/assets';
import { $ } from 'src/pages/assets';

export default defineComponent({
  mixins: [documentUtil],
  props: {},
  data() {
    return {
      mobile_table_columns,
    };
  },
  emits: ['rowClick'],
  //   components: {

  //   },
  mounted: function () {
    this.handleTableColumns();
  },
  //   unmounted: function () {
  //   },
  methods: {
    expand(row_id: string) {
      const expand_more = $('#expand_more_' + row_id) as HTMLElement;
      const expand_less = $('#expand_less_' + row_id) as HTMLElement;

      if (expand_more) {
        expand_more.classList.toggle('hidden');
      }

      if (expand_less) {
        expand_less.classList.toggle('hidden');
      }

      this.displayHiddenColumns(row_id);
    },

    displayHiddenColumns(row_id: string) {
      const elements = document.querySelectorAll('.mark_hidden_' + row_id);
      if (elements) {
        elements.forEach((element) => {
          element.classList.toggle('hidden');
        });
      }
    },
    handleTableColumns(update_loading_flag = true) {
      try {
        this.table_columns = [];
        for (const [name, column] of Object.entries(mobile_table_columns)) {
          this.table_columns.push(column);
        }
        // sort
        this.table_columns.sort((a: any, b: any) => {
          return a.order - b.order;
        });
      } catch (err) {
        logError(err);
      } finally {
      }
    },
  },
  setup() {
    const task_store = useTaskStore();
    const { tasks } = storeToRefs(task_store);

    return {
      tasks,
      table_columns: ref([] as dynamicObj[]),
    };
  },
});
</script>
