<template>
    <div class="full-width dashboard-list-area" v-if="list_mode">
      <DocBitsTable
        v-if="table_columns.length > 0"
        :rows="tasks"
        :columns="v2TableColumns"
        row-key="id"
        table-id="tasks-table"
        :loading="show_table_loader"
        :features="v2TableFeatures"
        :row-actions="v2RowActions"
        :pagination="v2PaginationState"
        :rows-per-page-options="[10, 20, 25, 50]"
        pagination-label="tasks_pagination_size"
        :pagination-settings-key="pagination_settings_key"
        no-data-label="no_document_found"
        :column-order="v2ColumnOrder"
        table-class="dashboard-height-tabs"
        @update:sorting="handleV2Sort"
        @update:pagination="handleV2Pagination"
        @selection-change="handleV2SelectionChange"
        @column-reorder="handleV2ColumnReorder"
        @row-click="handleV2RowClick"
        @row-action="handleV2RowAction"
      >
        <!-- Header Actions - Bulk Actions Menu -->
        <template #header-actions="{ selectedCount }">
          <q-btn flat dense round @click.stop.prevent icon="more_horiz" :disable="selectionList.length === 0">
            <q-menu auto-close transition-show="jump-down" transition-hide="jump-up" anchor="bottom middle" self="top middle">
              <q-list dense style="min-width: 100px">
                <q-separator v-if="canDeleteSelection" inset/>
                <q-item v-if="canDeleteSelection" clickable>
                  <q-item-section @click="deleteSelection">
                    <span class="text-red">
                      {{$t('delete')}}
                    </span>
                  </q-item-section>
                </q-item>
                <q-item v-if="canBulkMarkAsDone" :clickable="canBulkMarkAsDone">
                  <q-item-section @click="bulkUpdateStatusTasks(selectionList, 'done')">
                    <span>
                      {{$t('mark_as_done')}}
                    </span>
                  </q-item-section>
                </q-item>
                <q-item v-if="canBulkMarkAsUnDone" :clickable="canBulkMarkAsUnDone">
                  <q-item-section @click="bulkUpdateStatusTasks(selectionList, 'open')">
                    <span>
                      {{$t('mark_as_open')}}
                    </span>
                  </q-item-section>
                </q-item>
              </q-list>
            </q-menu>
          </q-btn>
        </template>

        <!-- Title Column - Clickable with primary color -->
        <template #body-cell-title="{ row }">
          <span class="text-primary cursor-pointer" @click.stop="rowClick('title', row)">
            {{ row['title'] || '-' }}
          </span>
          <q-tooltip v-if="row['title']">{{ row['title'] }}</q-tooltip>
        </template>

        <!-- Document Name Column - Clickable with primary color -->
        <template #body-cell-document_name="{ row }">
          <span class="text-primary cursor-pointer" @click.stop="rowClick('document_name', row)">
            {{ row['document_name'] || '-' }}
          </span>
          <q-tooltip v-if="row['document_name']">{{ row['document_name'] }}</q-tooltip>
        </template>

        <!-- Status Column - Badge -->
        <template #body-cell-status="{ row }">
          <span>
            <q-badge align="middle" :class="getStatusClass(row['status'])">
              <span style="padding: 2px" class="dashboard-status-text">{{ getLabelTranslation(row['status']) }}</span>
            </q-badge>
          </span>
          <q-tooltip>{{ getLabelTranslation(row['status']) }}</q-tooltip>
        </template>

        <!-- Deadline Column -->
        <!-- DTLG-54: deadlines are stored as UTC; render UTC-aware so every -->
        <!-- viewer sees the same instant in local time (matches Board/Detail). -->
        <template #body-cell-deadline="{ row }">
          {{ formatDateTimeZone(row['deadline']) }}
        </template>

        <!-- Created On Column -->
        <template #body-cell-created_on="{ row }">
          {{ formatDateAccordingToPreference(row['created_on']) }}
        </template>

        <!-- Assigned To Column -->
        <template #body-cell-assigned_to_user="{ row }">
          <span class="inline-flex items-center gap-1">
            <Icon v-if="row.assigned_to_group != null" icon="mdi:account-group" width="20" height="20" />
            {{ row['assigned_to_user'] ? row['assigned_to_user'] : row['assigned_to_group'] ? row['assigned_to_group'] : '-' }}
          </span>
        </template>

      </DocBitsTable>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { storeToRefs } from 'pinia';
import { LocalStorage } from 'quasar';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import documentUtil from 'src/utils/documentUtil';
import dragDropColumn from 'src/mixins/dragDropColumn';
import { toPositiveInt } from 'src/utils/general';
import { useTaskStore, useSettingStore } from 'src/store/main';
import { table_columns } from 'src/pages/Tasks/List/table_columns';
import { isUserAdmin } from 'src/utils/UserDetails';
import {
  toTaskDeletePermission,
  canDeleteTaskRow,
} from 'src/utils/taskDeletePermission';
import { tasks_non_admin_delete_permission_setting } from 'src/constants';
import { DocBitsTable } from 'src/components/Table';
import type {
  UnifiedTableColumn,
  SortEventPayload,
  RowClickPayload,
  PaginationChangePayload,
  RowActionItem,
  RowActionPayload,
} from 'src/components/Table';

export default defineComponent({
  el: '#app',
  mixins: [dateUtils, helperMixin, documentUtil, dragDropColumn],
  components: {
    DocBitsTable,
  },
  emits: [
    'deleteSelection',
    'deleteRecord',
    'bulkUpdateStatusTasks',
    'nexPageClicked',
    'rowClick',
  ],
  data() {
    return {
      pagination_settings_key: 'TASK_PAGINATION_SIZE',
    };
  },

  mounted() {
    try {
      this.headerCheckbox = false;
      this.handleTableColumns(true);

      this.initDragDropColumns('tasks-table', 'translation_key');
    } catch (err) {
      logError(err);
    }
  },

  watch: {
    tasks: {
      handler: function (newVal, oldVal) {
        this.selectionList.forEach((id: any) => {
          const task = this.tasks.find((task: any) => task.id === id);
          if (task) {
            task.rowSelection = true;
          }
        });
      },
    },
  },

  computed: {
    isAdmin(): boolean {
      return isUserAdmin();
    },

    taskDeletePermission(): string {
      return toTaskDeletePermission(
        this.org_based_settings[tasks_non_admin_delete_permission_setting],
      );
    },

    // Bulk delete is all-or-nothing on the backend: one forbidden task in
    // the selection fails the whole request with 403. Only offer it when
    // every selected row is individually deletable.
    canDeleteSelection(): boolean {
      return this.selectionList.every((id: any) => {
        const task = this.tasks.find((t: any) => t.id === id);
        return task && this.canDeleteRow(task);
      });
    },

    v2TableColumns(): UnifiedTableColumn[] {
      const cols: UnifiedTableColumn[] = this.table_columns.map((col: dynamicObj) => ({
        name: col.name,
        label: this.$t(col.translation_key || col.name),
        field: col.name,
        sortable: col.sortable === true,
        align: 'left' as const,
      }));
      return cols;
    },

    v2ColumnOrder(): string[] {
      return this.table_columns.map((col: dynamicObj) => col.name);
    },

    v2TableFeatures() {
      return {
        sorting: true,
        filtering: false,
        selection: true,
        bulkActions: false,
        rowActions: true,
        resizable: true,
        pagination: true,
        columnReorder: true,
      };
    },

    v2PaginationState() {
      return {
        sortBy: this.sort_by || null,
        descending: this.sort_order === 'desc',
        page: this.current_page,
        rowsPerPage: Number(this.page_size) || 10,
        rowsNumber: this.total_pages * (Number(this.page_size) || 10),
      };
    },

    v2RowActions(): RowActionItem[] {
      return [
        {
          key: 'mark_as_done',
          label: 'mark_as_done',
          icon: 'check_circle',
          show: (row: any) => row.status !== 'done' && !this.isHasAccess(row),
        },
        {
          key: 'mark_as_open',
          label: 'mark_as_open',
          icon: 'radio_button_unchecked',
          show: (row: any) => row.status === 'done' && !this.isHasAccess(row),
        },
        {
          key: 'delete',
          label: 'delete',
          icon: 'delete',
          color: 'red',
          separator: true,
          show: (row: any) => this.canDeleteRow(row),
        },
      ];
    },

    canBulkMarkAsDone(): boolean {
      return this.selectionList.length > 0 && this.selectionList.every((id: any) => {
        const task = this.tasks.find((t: any) => t.id === id);
        return task && task.status !== 'done';
      });
    },

    canBulkMarkAsUnDone(): boolean {
      return this.selectionList.length > 0 && this.selectionList.every((id: any) => {
        const task = this.tasks.find((t: any) => t.id === id);
        return task && task.status !== 'open';
      });
    },
  },

  methods: {
    getStatusClass(status: string) {
      let status_class = 'bg-grey';
      const status_exists = this.statusList.hasOwnProperty(status);
      if (status_exists) {
        status_class = this.statusList[status]['class'];
      }
      status_class += ' dashboard-status-badge';
      return status_class;
    },

    canDeleteRow(row: any): boolean {
      return canDeleteTaskRow({
        isAdmin: this.isAdmin,
        permission: this.taskDeletePermission,
        taskCreatedBy: row.created_by,
        currentUserId: this.userId,
        taskBelongsToSomeoneElse: this.isHasAccess(row),
      });
    },

    bulkUpdateStatusTasks(selectionList: any[], status: string) {
      const validRows = selectionList.filter((id) => {
        const row = this.tasks.find((task) => task.id === id);
        return row && !this.isHasAccess(row);
      });
      if (validRows.length === 0) {
        notify.error(this.$t('task_permission_error_for_non_admin'));
        return;
      }
      this.$emit('bulkUpdateStatusTasks', selectionList, status);
    },

    deleteSelection() {
      this.$emit('deleteSelection');
    },

    deleteRecord(task: any) {
      this.$emit('deleteRecord', task.id);
    },

    handleV2Sort(payload: SortEventPayload) {
      if (payload.column && payload.direction) {
        this.setOrderBy(payload.column, payload.direction);
      } else {
        this.setDefaultSort();
      }
      this.current_page = 1;
      this.$emit('nexPageClicked');
    },

    handleV2Pagination(payload: PaginationChangePayload) {
      // Guard the v2-table entry at the source. DocBitsTable emits rowsPerPage/
      // page on its raw event payload WITHOUT coercion (its `?? 50`/`?? 10`
      // defaults only apply to the display object), and these write straight into
      // the shared task store via storeToRefs. An undefined/NaN/0 value would
      // poison page_size -> offset (skip=NaN) -> HTTP 422 / "NaN / NaN". DOCB-12859.
      // Covered by src/tests/unit/tasks/task-pagination-nan.unit.spec.ts.
      this.page_size = toPositiveInt(payload.rowsPerPage, 10);
      this.current_page = toPositiveInt(payload.page, 1);
      this.$emit('nexPageClicked');
    },

    handleV2SelectionChange(payload: { selectedIds: string[]; selectedRows: any[]; totalSelected: number; totalAvailable: number }) {
      this.selectionList = payload.selectedIds;
      this.headerCheckbox = payload.totalSelected === payload.totalAvailable && payload.totalAvailable > 0;
    },

    handleV2ColumnReorder(columnNames: string[]) {
      const formattedColumnsObj = {} as dynamicObj;
      columnNames.forEach((name: string, index: number) => {
        const col = this.table_columns.find((c: any) => c.name === name);
        if (col) {
          formattedColumnsObj[name] = {
            name: col.name,
            order: index,
            sortable: col.sortable ? true : false,
            translation_key: col.translation_key,
          };
        }
      });
      this.saveTaskColumns(formattedColumnsObj);
    },

    rowClick(column_name: string, row: any) {
      this.$emit('rowClick', column_name, row);
    },

    handleV2RowClick(payload: RowClickPayload) {
      // Generic row click - no column info available from DocBitsTable
      // Specific column clicks (title, document_name) are handled via body-cell slots
    },

    handleV2RowAction(payload: RowActionPayload) {
      const { row, action } = payload;
      if (action === 'delete') {
        this.deleteRecord(row);
      } else if (action === 'mark_as_done') {
        this.$emit('bulkUpdateStatusTasks', [row.id], 'done');
      } else if (action === 'mark_as_open') {
        this.$emit('bulkUpdateStatusTasks', [row.id], 'open');
      }
    },

    handleTableColumns(update_loading_flag = true) {
      try {
        let preferredColumns = table_columns as dynamicObj;
        let savedColumns = this.user_settings[this.columnKey];
        if (!Object.keys(this.user_settings).length) {
          savedColumns = LocalStorage.getItem(this.columnKey);
          if (savedColumns) {
            savedColumns = JSON.parse(savedColumns);
          }
        } else if (savedColumns) {
          savedColumns = JSON.parse(savedColumns);
        }
        if (
          savedColumns &&
          Object.keys(savedColumns).length ==
            Object.keys(preferredColumns).length
        ) {
          preferredColumns = savedColumns;
        }
        LocalStorage.set(this.columnKey, JSON.stringify(preferredColumns));
        this.processing = true;
        this.table_columns = [];
        for (const [name, column] of Object.entries(preferredColumns)) {
          this.table_columns.push(column as dynamicObj);
        }
        this.table_columns.sort((a: any, b: any) => {
          return a.order - b.order;
        });
      } catch (err) {
        logError(err);
      } finally {
        if (update_loading_flag) {
          this.processing = false;
        }
      }
    },

  },
  setup() {
    const settingStore = useSettingStore();
    const { user_settings, org_based_settings } = storeToRefs(settingStore);
    const task_store = useTaskStore();
    const {
      tasks,
      list_mode,
      page_size,
      processing,
      columnKey,
      selectionList,
      headerCheckbox,
      statusList,
      total_pages,
      current_page,
      show_table_loader,
      userGroupIds,
      userId,
      sort_by,
      sort_order,
    } = storeToRefs(task_store);
    const { saveTaskColumns, isHasAccess, setOrderBy, setDefaultSort } = task_store;

    return {
      tasks,
      list_mode,
      page_size,
      columnKey,
      processing,
      statusList,
      total_pages,
      current_page,
      user_settings,
      org_based_settings,
      selectionList,
      headerCheckbox,
      show_table_loader,
      sort_by,
      sort_order,
      table_columns: ref([] as dynamicObj[]),
      saveTaskColumns,
      setOrderBy,
      setDefaultSort,
      userGroupIds,
      userId,
      isHasAccess,
    };
  },
});
</script>

