<template>
  <q-select
    class="q-mr-sm"
    dense
    style="width: 227px"
    outlined
    multiple
    emit-value
    map-options
    :options="statusOptions"
    v-model="selected_value"
    @update:model-value="
      (val: any) => {
        valueUpdated(val);
      }
    "
    :label="$t('status')"
  >
    <template v-slot:option="{ itemProps, selected, opt, toggleOption }">
      <q-item v-bind="itemProps">
        <q-item-section side>
          <q-checkbox
            :model-value="selected"
            @update:model-value="toggleOption(opt)"
          ></q-checkbox>
        </q-item-section>
        <q-item-section>
          <div>{{ $t(opt.label) }}</div>
        </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useTaskStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { isUndefinedOrNull } from 'src/utils/general';
import { status_list } from 'src/constants/enum';
import type { dynamicObj } from 'src/pages/assets';

export default defineComponent({
  mixins: [],
  props: {},
  watch: {
    taskfiltersMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadSavedFiler();
      },
    },
  },
  data() {
    return {};
  },
  mounted() {
    this.statusOptions = status_list.map((item: any) => {
      return {
        label: this.$t(item),
        value: item,
      };
    });

    this.loadSavedFiler();
  },
  unmounted: function () {
    // unmount
  },

  methods: {
    loadSavedFiler() {
      const status = this.taskfiltersMap.get('status');
      if (isUndefinedOrNull(status) || status == '') {
        this.selected_value = [];
        return;
      }

      if (typeof status === 'string') {
        this.selected_value = status.split(',').filter((s) => s.length > 0);
      } else if (Array.isArray(status)) {
        this.selected_value = status.map((item: any) =>
          typeof item === 'string' ? item : item?.value,
        );
      } else {
        this.selected_value = [];
      }
    },

    valueUpdated(val: any) {
      this.selected_value = val;
      if (this.handleEmptyValue()) {
        return;
      }
      this.setItemInFiltersMap('status', this.selected_value.join(','));
      this.triggerApplyFilters();
    },

    handleEmptyValue() {
      if (
        isUndefinedOrNull(this.selected_value) ||
        this.selected_value.length == 0
      ) {
        this.deleteItemInFiltersMap('status');
        this.triggerApplyFilters();
        return true;
      }
      return false;
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },
  },
  setup() {
    const task_store = useTaskStore();
    const { taskfiltersMap } = storeToRefs(task_store);
    const { setItemInFiltersMap, deleteItemInFiltersMap } = task_store;

    return {
      selected_value: ref([] as string[]),
      statusOptions: ref([] as dynamicObj[]),
      taskfiltersMap,

      setItemInFiltersMap,
      deleteItemInFiltersMap,
    };
  },
});
</script>
<style lang="scss"></style>
