<template>
  <div class="filter-badges row q-ml-md q-mb-sm">
    <template v-for="key in taskfiltersMap" :key="key">
      <div v-if="key[0] == 'status'" class="row">
        <div
          v-for="(filter, index) in statusList(key[1])"
          :key="filter"
        >
          <q-badge rounded color="primary" class="q-mr-sm capitalize">
            <template v-slot>
              {{ $t(filter) }}

              <q-icon
                name="close"
                color="white"
                class="q-ml-xs cursor-pointer"
                @click="removeStatusItem(filter, index)"
              />
            </template>
          </q-badge>
        </div>
      </div>
      <div v-else-if="key[0] == 'keyword'">
        <div class="row">
          <q-badge rounded color="primary" class="q-mr-sm capitalize">
            <template v-slot>
              {{ key[1] }}
              <q-icon
                name="close"
                color="white"
                class="q-ml-xs cursor-pointer"
                @click="removeFilter(key[0])"
              />
            </template>
          </q-badge>
        </div>
      </div>
      <div v-else-if="key[0] == 'priority'">
        <div class="row">
          <q-badge rounded color="primary" class="q-mr-sm capitalize">
            <template v-slot>
              {{ key[1]['value'] }}
              <q-icon
                name="close"
                color="white"
                class="q-ml-xs cursor-pointer"
                @click="removeFilter(key[0])"
              />
            </template>
          </q-badge>
        </div>
      </div>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useTaskStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  props: {},
  mounted() {
    this.init();
  },
  unmounted: function () {
    // unmoutned
  },
  methods: {
    init() {
      //   init
    },

    statusList(value: any): string[] {
      if (typeof value === 'string') {
        return value.split(',').filter((s) => s.length > 0);
      }
      if (Array.isArray(value)) {
        return value.map((item: any) =>
          typeof item === 'string' ? item : item?.value,
        );
      }
      return [];
    },

    removeStatusItem(item: string, item_index: number) {
      const list = this.statusList(this.taskfiltersMap.get('status'));
      list.splice(item_index, 1);

      if (list.length == 0) {
        this.removeFilter('status');
        return;
      }

      this.setItemInFiltersMap('status', list.join(','));
      this.triggerApplyFilters();
    },

    removeFilter(key: string, index?: number) {
      this.deleteItemInFiltersMap(key);

      if (key == 'keyword') {
        const event = new CustomEvent('delete_input_text', { detail: {} });
        document.dispatchEvent(event);
      }

      this.triggerApplyFilters();
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },
  },
  setup() {
    const task_store = useTaskStore();
    const { taskfiltersMap, taskListSettingsMap } = storeToRefs(task_store);
    const { deleteItemInFiltersMap, setItemInFiltersMap } = task_store;

    return {
      deleteItemInFiltersMap,
      setItemInFiltersMap,
      taskfiltersMap,
      taskListSettingsMap,
    };
  },
});
</script>
