<template>
  <q-input
    dense
    v-model="searchInput"
    class="search-invoices"
    :class="searchInput.length === 0 ? 'search-in-active' : 'search-active'"
    autofocus
    :placeholder="$t('task_quick_search_placeholder')"
    outlined
    @update:model-value="inputValueChanges()"
    @keyup.enter="triggerSearchOnEnter"
  >
    <template v-slot:append>
      <f-btn icon="tune" appearance="flat">
        <q-menu
          style="width: 500px; min-height: 250px"
          anchor="bottom start"
          self="top left"
          :offset="[453, 10]"
        >
          <div class="q-pa-md">
            <div class="row q-my-sm">
              <span style="margin-top: 10px">{{ $t('status') }}</span>
              <q-space />
              <StatusFilter />
            </div>

            <div class="row q-my-sm">
              <span style="margin-top: 10px">{{ $t('priority') }}</span>
              <q-space />
              <PriorityFilter />
            </div>

            <div class="row q-my-sm">
              <span style="margin-top: 10px">{{ $t('assigned_to') }}</span>
              <q-space />
              <UserFilter />
            </div>

            <div class="row q-my-sm">
              <span style="margin-top: 10px">{{ $t('pagination_size') }}</span>
              <q-space />
              <PaginationSettings />
            </div>

            <div class="float-right q-ml-auto">
              <f-btn
                appearance="secondary"
                class="q-mr-sm mt-20 q-mb-md"
                :label="$t('clear_filters')"
                @click="resetFilters()"
              />
            </div>
          </div>
        </q-menu>
      </f-btn>
    </template>
  </q-input>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useTaskStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { debounce } from 'quasar';
import PaginationSettings from './Filters/pagination-settings.vue';
import StatusFilter from './Filters/status-filter.vue';
import PriorityFilter from './Filters/priority-filter.vue';
import UserFilter from './Filters/user-filter.vue';

export default defineComponent({
  mixins: [],
  props: {},
  components: {
    StatusFilter,
    PaginationSettings,
    PriorityFilter,
    UserFilter,
  },
  watch: {
    taskfiltersMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadSavedFiler();
      },
    },
  },
  mounted() {
    this.debounceSearchInputFunc = debounce(() => {
      this.triggerApplyFilters();
    }, 1000);
    document.addEventListener('delete_input_text', this.clearSearchInput);
  },
  methods: {
    clearSearchInput() {
      this.searchInput = '';
    },

    resetFilters() {
      const event = new CustomEvent('reset_filters', {});
      document.dispatchEvent(event);
    },

    loadSavedFiler() {
      let keyword = this.taskfiltersMap.get('keyword');
      if (!keyword) {
        keyword = '';
      }

      this.searchInput = keyword;
    },

    triggerSearchOnEnter(event: any) {
      if (event.keyCode !== 13) {
        return;
      }

      this.inputValueChanges();
    },

    inputValueChanges() {
      if (this.searchInput) {
        this.searchInput = this.searchInput.trim();
      }

      if (this.searchInput.length == 0) {
        this.deleteItemInFiltersMap('keyword');
        this.debounceSearchInputFunc();
        return;
      }

      this.oldSearchInput = this.searchInput;

      this.setItemInFiltersMap('keyword', this.searchInput);
      this.debounceSearchInputFunc();
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', {
        detail: {
          reset_pagination: this.reset_pagination,
        },
      });
      document.dispatchEvent(event);
    },
  },
  setup() {
    const task_store = useTaskStore();
    const { taskfiltersMap } = storeToRefs(task_store);
    const { setItemInFiltersMap, deleteItemInFiltersMap } = task_store;

    return {
      deleteItemInFiltersMap,
      setItemInFiltersMap,

      searchInput: ref(''),
      oldSearchInput: ref(''),
      taskfiltersMap,

      debounceSearchInputFunc: {} as any,
      reset_pagination: ref(true),
    };
  },
});
</script>
