<template>
  <div class="row q-mb-md">
    <div style="margin-top: 40px" class="dashboard-title dark-readable">
      {{ $t('all_tasks') }} ({{ total_records }})
    </div>
    <div class="col">
      <div class="row justify-start">
        <div class="dashboard-search-box q-ml-md mt-20">
          <quickSearch />
        </div>

        <div class="dashboard-search-box q-ml-md mt-20">
          <userFilter />
        </div>

        <q-space />
        <f-btn
          square
          class="q-mr-sm mt-20"
          @click="refreshFilters"
        >
          <Icon icon="mdi:refresh" width="20" height="20" />
          <q-tooltip>{{ $t('refresh_list') }}</q-tooltip>
        </f-btn>

        <f-btn
          square
          class="q-mr-sm mt-20"
          icon="dashboard"
          @click="changeListMode()"
        >
          <q-tooltip>{{ $t('change_view') }}</q-tooltip>
        </f-btn>
      </div>
    </div>
  </div>

  <div class="q-mt-sm">
    <filterBadges />
  </div>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import cacheUtil from 'src/utils/cache';
import quickSearch from './quick-search.vue';
import { useTaskStore } from 'src/store/main';
import { CONSTANTS } from 'src/constants';
import userFilter from './Filters/user-filter.vue';
import keyboard from 'src/pages/Dashboard/keyboard';
import filterBadges from './Filters/filter-badges.vue';

export default defineComponent({
  mixins: [keyboard, cacheUtil],
  props: {},
  watch: {},
  emits: ['fetchData'],
  components: {
    
    userFilter,
    quickSearch,
    filterBadges,
  },
  mounted: function () {
    // mounted
  },
  unmounted: function () {
    // unmounted
  },
  methods: {
    refreshFilters() {
      const event = new CustomEvent('refresh_view', {
        detail: { show_shimmer_loader: true },
      });
      document.dispatchEvent(event);
    },
    changeListMode() {
      this.list_mode = !this.list_mode;
      this.setDataToLocalStorage(CONSTANTS.tasks_list_mode, this.list_mode);
      this.$emit('fetchData', true);
    },
  },
  setup() {
    const task_store = useTaskStore();
    const { total_records, list_mode } = storeToRefs(task_store);

    return {
      list_mode,
      total_records,
    };
  },
});
</script>
<style lang="scss">
.p-4-8 {
  padding: 4px 8px;
}
</style>
