<template>
  <q-select
    ref="q-select"
    class="q-mr-sm user-filter-select"
    dense
    outlined
    v-model="selected_value"
    :options="user_options"
    @update:model-value="valueUpdated"
    :label="$t('assigned_to')"
  >
    <template v-slot:selected-item="scope">
      <div class="ellipsis">{{ scope.opt.label }}</div>
    </template>
  </q-select>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useTaskStore, useSettingStore } from 'src/store/main';
import { isUndefinedOrNull } from 'src/utils/general';
import { isOrganisationAdmin } from 'src/utils/UserDetails';
import { toBoolPreference } from 'src/utils/preferenceBool';
import { tasks_allow_all_filter_non_admin_setting } from 'src/constants';

export default defineComponent({
  computed: {
    canSeeAll() {
      return (
        isOrganisationAdmin() ||
        toBoolPreference(
          this.org_based_settings[tasks_allow_all_filter_non_admin_setting],
        )
      );
    },
    user_options() {
      const options = [];
      if (this.canSeeAll) {
        options.push({ label: this.$t('all'), value: false });
      }
      options.push({ label: this.$t('assigned_to_me'), value: true });
      return options;
    },
  },
  watch: {
    taskfiltersMap: {
      deep: true,
      handler() {
        this.loadFilters();
      },
    },
  },

  mounted() {
    this.init();
  },

  methods: {
    init() {
      this.loadFilters();

      if (!this.canSeeAll) {
        const assignedToMe = this.user_options.find(
          (opt: any) => opt.value === true,
        );
        if (assignedToMe) {
          this.selected_value = assignedToMe;
          this.setItemInFiltersMap(this.filter_name, assignedToMe);
          this.triggerApplyFilters();
        }
      }
    },

    loadFilters() {
      const assigned_to = this.taskfiltersMap.get(this.filter_name);
      if (!assigned_to) {
        this.selected_value = '';
        return;
      }
      this.selected_value = assigned_to;
    },

    triggerApplyFilters() {
      document.dispatchEvent(new CustomEvent('apply_filters', { detail: {} }));
    },

    valueUpdated(val: any) {
      this.selected_value = val;

      if (this.selected_value === '' || isUndefinedOrNull(this.selected_value)) {
        this.deleteItemInFiltersMap(this.filter_name);
        this.triggerApplyFilters();
        return;
      }

      this.setItemInFiltersMap(this.filter_name, this.selected_value);
      this.triggerApplyFilters();
    },
  },

  setup() {
    const task_store = useTaskStore();
    const { taskfiltersMap } = storeToRefs(task_store);
    const { setItemInFiltersMap, deleteItemInFiltersMap } = task_store;
    const { org_based_settings } = storeToRefs(useSettingStore());
    return {
      setItemInFiltersMap,
      deleteItemInFiltersMap,
      taskfiltersMap,
      org_based_settings,
      selected_value: ref(''),
      filter_name: 'only_for_current_user',
    };
  },
});
</script>

<style lang="scss">
.user-filter-select {
  width: 227px;
}
</style>
