<template>
  <div
    class="task-card back-white shadow-1 rounded px-3 pt-3 pb-3 gray-border border-white"
    @click="clickCard"
  >
    <div class="row justify-between">
      <span class="task-description text-weight-medium task-title">{{
        task.title
      }}</span>
      <div>
        <q-icon
          v-if="task.status"
          class="on-left"
          :name="'img:/images/' + priorityIcon"
          size="sm"
        >
          <q-tooltip anchor="top middle" self="bottom middle">
            {{ $t(task.priority) }}
          </q-tooltip>
        </q-icon>
        <q-avatar
          v-if="task.assigned_to_user"
          size="24px"
          class="user-avatar-background"
        >
          <span class="user-item-initials initials-text-color">
            {{ getInitials(task.assigned_to_user) }}
          </span>
          <q-tooltip anchor="top middle" self="bottom middle">
            {{ task.assigned_to_user }}
          </q-tooltip>
        </q-avatar>
        <q-avatar
          v-else-if="task.assigned_to_group"
          size="24px"
          class="user-avatar-background"
        >
          <q-icon name="group" class="text-white" />
          <q-tooltip anchor="top middle" self="bottom middle">
            {{ task.assigned_to_group }}
          </q-tooltip>
        </q-avatar>
      </div>
      <!-- <p class="text-weight-medium tracking-wide text-sm text-capitalize">{{ $t(task.priority) }}</p> -->
    </div>
    <div class="q-mt-sm full-width no-paragraph-space">
      <p
        class="text-sm link task-document-link"
        @click="clickDocument"
        @click.stop.prevent
      >
        <q-icon name="description" class="q-mr-xs" />
        {{ task.document_name }}
        <q-tooltip>
          {{ $t('open_document') }}
        </q-tooltip>
      </p>
      <span v-if="task.description" class="text-sm task-description">{{
        task.description
      }}</span>
    </div>
    <div class="row mt-4 justify-between items-center">
      <span class="text-sm">{{
        formatDateAccordingToPreference(task.created_on)
      }}</span>
      <div class="hidden-child no-padding">
        <q-btn
          flat
          dense
          round
          @click.stop.prevent
          icon="more_horiz"
          size="12px"
        >
          <q-menu
            auto-close
            transition-show="jump-down"
            transition-hide="jump-up"
            anchor="bottom middle"
            self="top middle"
          >
            <q-list dense style="min-width: 100px">
              <q-item clickable>
                <q-item-section @click="clickUpdateStatus">
                  <span>
                    <template v-if="task.status == 'done'">
                      {{ $t('mark_as_open') }}
                    </template>
                    <template v-else>
                      {{ $t('mark_as_done') }}
                    </template>
                  </span>
                </q-item-section>
              </q-item>
              <q-separator v-if="canDeleteTask" inset />
              <q-item v-if="canDeleteTask" clickable>
                <q-item-section @click="clickRemove(task.id)">
                  <span class="text-red">
                    {{ $t('delete') }}
                  </span>
                </q-item-section>
              </q-item>
            </q-list>
          </q-menu>
        </q-btn>
      </div>
    </div>
  </div>
</template>
<script>
// import Badge from 'src/pages/Tasks/Board/badge.vue';
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { useSettingStore, useTaskStore } from 'src/store/main';
import { isUserAdmin } from 'src/utils/UserDetails';
import { canDeleteTaskRow } from 'src/utils/taskDeletePermission';
import { tasks_non_admin_delete_permission_setting } from 'src/constants';

export default {
  mixins: [dateUtils],
  components: {
    // Badge
  },
  props: {
    task: {
      type: Object,
      default: () => ({}),
    },
  },
  emits: [
    'cardClick',
    'documentClick',
    'deleteRecord',
    'updateStatusTaskClick',
  ],
  methods: {
    getInitials(fullname) {
      var names = fullname.split(' '),
        initials = names[0].substring(0, 1).toUpperCase();

      if (names.length > 1) {
        initials += names[names.length - 1].substring(0, 1).toUpperCase();
      }
       
      return initials;
    },
    clickCard() {
      this.$emit('cardClick', this.task);
    },
    clickDocument() {
      this.$emit('documentClick', this.task);
    },
    clickRemove() {
      this.$emit('deleteRecord', this.task);
    },
    clickUpdateStatus() {
      let status;
      if (this.task.status == 'done') {
        status = 'open';
      } else {
        status = 'done';
      }
      this.$emit('updateStatusTaskClick', this.task, status);
    },
  },
  computed: {
    isAdmin() {
      return isUserAdmin();
    },
    canDeleteTask() {
      return canDeleteTaskRow({
        isAdmin: this.isAdmin,
        permission:
          this.org_based_settings[tasks_non_admin_delete_permission_setting],
        taskCreatedBy: this.task.created_by,
        currentUserId: this.userId,
        taskBelongsToSomeoneElse: this.isHasAccess(this.task),
      });
    },
    priorityIcon() {
      const mappings = {
        medium: 'priority_medium.svg',
        high: 'priority_high.svg',
        low: 'priority_low.svg',
      };

      return mappings[this.task.priority] || mappings.default;
    },
  },
  setup() {
    const { org_based_settings } = storeToRefs(useSettingStore());
    const task_store = useTaskStore();
    const { userId } = storeToRefs(task_store);
    const { isHasAccess } = task_store;
    return { org_based_settings, userId, isHasAccess };
  },
};
</script>
