<template>
  <MessageBanner
    v-if="!user_settings[tasks_notification_setting]"
    :dissmiss_btn="false"
    :back_route="false"
    :message="$t('ACTION_NOT_ALLOWED')"
  />
  <template v-else>
    <SubHeader
      name="tasks"
      :label="$t('tasks')"
      :show_expiry_alert="true"
      :onSearch="false"
    >
    </SubHeader>

    <div v-if="isMobile()">
      <div class="full-width" v-if="tasks && tasks.length > 0">
        <MobileGrid @rowClick="rowClick" />
      </div>
      <q-markup-table class="full-width" v-else>
        <thead>
          <tr class="bg-grey-3">
            <th>{{ $t('no_data_found') }}</th>
          </tr>
        </thead>
      </q-markup-table>

      <div class="q-pa-lg flex flex-center">
        <tr v-if="total_pages > 0">
          <td class="text-center" colspan="10">
            <q-pagination
              v-model="current_page"
              color="primary"
              :max="total_pages"
              :max-pages="6"
              boundary-links
              @click="nexPageClicked()"
            />
          </td>
        </tr>
      </div>
    </div>
    <div v-else class="dashboard-container dashboard-text-color dashboard-main-tasks" data-test="tasks-page-desktop">
      <Header @fetchData="fetchData" />

      <q-separator class="seperator" />

      <template v-if="getListMode()">
        <List
          @deleteRecord="deleteRecord"
          @deleteSelection="deleteSelection"
          @bulkUpdateStatusTasks="bulkUpdateStatusTasks"
          @nexPageClicked="nexPageClicked"
          @rowClick="rowClick"
        />
      </template>
      <template v-else>
        <TaskBoard
          @deleteRecord="deleteRecord"
          @routeByStatus="routeByStatus"
          @bulkUpdateStatusTasks="bulkUpdateStatusTasks"
        />
      </template>

      <!-- <div class="q-pa-lg flex flex-center">
      <tr v-if="total_pages > 0">
        <td class="text-center" colspan="10">
          <q-pagination
            v-model="current_page"
            color="primary"
            :max="total_pages"
            :max-pages="6"
            boundary-links
            @click="nexPageClicked()"
          />
        </td>
      </tr>
    </div> -->
    </div>

    <Loader />
  </template>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { api } from 'pages/APIs';
import { debounce } from 'quasar';
import { storeToRefs } from 'pinia';
import Header from './List/header.vue';
import cacheUtil from 'src/utils/cache';
import { defineComponent, ref } from 'vue';
import List from 'src/pages/Tasks/List.vue';
import type { dynamicObj } from 'src/pages/assets';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import MobileGrid from './List/MobileGrid.vue';
import helperMixin from 'src/mixins/helperMixin';
import documentUtil from 'src/utils/documentUtil';
import { toPositiveInt } from 'src/utils/general';
import TaskBoard from 'src/pages/Tasks/Board.vue';
import { ApiExceptions } from 'src/exceptions/index';
import dragDropColumn from 'src/mixins/dragDropColumn';
import MessageBanner from 'src/components/MessageBanner.vue';
import { taskApiService, genericService } from 'src/services';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import {
  approve_before_export_v2,
  tasks_pagination_size,
  tasks_notification_setting,
  CONSTANTS,
} from 'src/constants';
import {
  useWebSocketStore,
  useTaskStore,
  useDocAttributesStore,
  useUserStore,
  useSettingStore,
} from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [cacheUtil,
    helperUtil,
    helperMixin,
    documentUtil,
    dragDropColumn,
  ],
  components: {
    List,
    Header,
    Loader,
    SubHeader,
    TaskBoard,
    MobileGrid,
    MessageBanner,
  },
  data() {
    return {
      InvoicesClearInterval: 0 as any,
      debounceSearchInputFunc: {} as any,
      tasks_notification_setting,
    };
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    // Before leaving this page, lets first reset everything
    this.intervalManager(false);
    this.unsubscribeToChannel('dashboard');
    next();
  },

  mounted() {
    this.loadUserAcls();
    this.startSettingsFetch();

    try {
      (<any>window).dash = this;
      // this.fetchData(true)
      this.headerCheckbox = false;
      this.getSavedListSettings();
      this.loadData();
      this.intervalManager(true);
      this.getDocTypeAllSettings();
      // this.handleTableColumns

      document.addEventListener('reset_filters', this.resetFilters);
      document.addEventListener('refresh_view', this.refreshFilters);
      document.addEventListener('apply_filters', this.applyFilterEvent);
      document.addEventListener('update_task_list', this.updateTasksList);

      this.debounceSearchInputFunc = debounce(() => {
        this.applyFilter();
      }, 1000);

      this.prepareStatusList();
    } catch (err) {
      logError(err);
    }
  },
  unmounted: function () {
    document.removeEventListener('reset_filters', this.resetFilters);
    document.removeEventListener('refresh_view', this.refreshFilters);
    document.removeEventListener('apply_filters', this.applyFilterEvent);
    document.removeEventListener('update_task_list', this.updateTasksList);
  },
  watch: {
    tasks: {
      handler: function (newVal, oldVal) {
        this.selectionList.forEach((id: any) => {
          const task = this.tasks.find((task: any) => task.id === id);
          if (task) {
            task.rowSelection = true;
          }
        });
        this.reCalulcateTotalCount();
      },
    },
    processing: {
      handler: function (newVal, oldVal) {
        if (newVal == true) {
          this.showLoading();
        } else {
          this.hideLoading();
        }
      },
    },
    websocketHasError: {
      handler: function (newVal, oldVal) {
        if (newVal == true) {
          this.use_websocket = false;
        }
      },
    },
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == true && oldVal == false) {
          return;
        }
        this.reCalulcateTotalCount();
      },
    },
    page_size: 'fetchData',
  },
  methods: {
    prepareStatusList() {
      this.statusList['open'] = [];
      this.statusList['open']['value'] = 'open';
      this.statusList['open']['class'] = 'bg-blue-14';

      this.statusList['in_progress'] = [];
      this.statusList['in_progress']['value'] = 'in_progress';
      this.statusList['in_progress']['class'] = 'bg-amber-7';

      this.statusList['done'] = [];
      this.statusList['done']['value'] = 'done';
      this.statusList['done']['class'] = 'bg-light-green-6';

      this.statusList['rejected'] = [];
      this.statusList['rejected']['value'] = 'rejected';
      this.statusList['rejected']['class'] = 'bg-red-13';
    },

    deleteSelection() {
      this.bulkDeleteRecords(this.selectionList);
      const event = new CustomEvent('refresh_view', {});
      document.dispatchEvent(event);
    },

    async bulkUpdateStatusTasks(selectionList: any[], status: string) {
      try {
        this.processing = true;
        const response = await taskApiService.bulkUpdateStatusTasks(
          selectionList,
          status,
        );
        if (response.success === false) {
          throw response;
        }

        const event = new CustomEvent('refreshTasks', {});
        document.dispatchEvent(event);

        selectionList.forEach((id: any) => {
          const task = this.tasks.find((task: any) => task.id === id);
          if (task) {
            task.status = status;
            task.rowSelection = false;
          }
        });

        // this will only works in case of tasks board
        if (!this.getListMode()) {
          this.formatTaskList();
        }

        if (status === 'done') {
          this.adjustCountForDoneTasks(selectionList.length);
        }

        this.selectionList = [];
        notify.success(this.$t('status_updated_successfully'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    applyFilterEvent(e: any) {
      this.resetPagination();
      this.applyFilter();
    },

    intervalManager(intervalFlag: boolean) {
      clearInterval(this.InvoicesClearInterval);
      if (intervalFlag === true) {
        this.InvoicesClearInterval = setInterval(() => {
          this.fetchData(false);
        }, 60000);
      }
    },

    handleActions(id: any) {
      this.tasks.forEach((row: any, index: any) => {
        if (index !== id) {
          row['fabAction'] = false;
        }
      });
      return true;
    },

    resetPages() {
      this.resetPagination();
      this.fetchData();
    },

    applyFilter() {
      this.processing = true;
      this.resetAllSelectedRows();
      this.fetchData();
    },

    refreshFilters(e: any) {
      this.tasks = [];
      this.selectionList = [];
      this.headerCheckbox = false;
      this.fetchData();
    },

    async fetchData(show_loading = true) {
      try {
        if (show_loading) {
          this.processing = true;
          this.show_table_loader = true;
        }

        this.selectionList = [];
        this.headerCheckbox = false;

        const params = this.getSavedFiltersAsJson();
        if (!this.getListMode()) {
          params['limit'] = 100;
        }
        params['document_fields'] = 'supplier_name,supplier_id';
        params['cache'] = false;

        const sub_org_id = await this.getSubOrgId();
        if (sub_org_id && this.sub_org_id != this.getOrgId()) {
          params['sub_org_id'] = sub_org_id;
        }

        if (this.use_websocket) {
          let resp = await this.getWebSocketDashboard();
          // add wait for 5 second if there is till no response then switch to https
          if (resp != true) {
            setTimeout(this.handleWebsocketDelay, 5000);
          }
          return;
        }

        await this.getTasks(params);
        this.updateTableData();

        this.formatTaskList();

        setTimeout(this.turnOnWebSocket, 5000);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    handleWebsocketDelay() {
      // websocket is still fetching data and we are not getting any response
      if (this.data_status === 'received') {
        return;
      }
      logInfo('turning off websocket and switching to https', this.data_status);
      this.use_websocket = false;
      this.fetchData();
      setTimeout(this.turnOnWebSocket, 5000);
    },

    turnOnWebSocket() {
      if (this.websocketHasError) {
        return;
      }

      this.use_websocket = false;
    },

    updateTableData() {
      this.setPagination();
      this.applyCustomFormatOnRows();
      this.show_table_loader = false;
      this.processing = false;
    },

    setPagination() {
      if (this.total_records > 0) {
        this.setTotalPages();
      }
    },

    resetPagination() {
      this.total_pages = 0;
      this.current_page = 1;
      this.total_records = 0;
      this.offset = 0;
    },

    setTotalPages() {
      this.total_pages = Math.ceil(this.total_records / this.page_size);
    },

    calculateOffset() {
      this.offset = this.page_size * (this.current_page - 1);
    },

    nexPageClicked() {
      this.calculateOffset();
      this.fetchData();
    },

    applyCustomFormatOnRows() {
      this.tasks.forEach((row: any) => {
        row['fabAction'] = false;
        row['rowSelection'] = false;

        const { formatted_deadline } = this.getDisplayDeadline(row['deadline']);
        row['deadline'] = formatted_deadline;
      });
    },

    loadData() {
      this.resetPagination();
      this.applyFilter();
    },
    async bulkDeleteRecords(tasks_id: string[]) {
      try {
        this.processing = true;
        const response = await taskApiService.bulkDeleteTasks(tasks_id);
        if (response.success === false) {
          throw response;
        }

        await this.fetchData();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
        const event = new CustomEvent('refresh_view', {});
        document.dispatchEvent(event);
      }
    },
    async deleteRecord(id: string) {
      try {
        this.processing = true;
        const response = await taskApiService.deleteTask(id);
        if (response.success === false) {
          throw response;
        }

        await this.fetchData();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;

        const event = new CustomEvent('refresh_view', {});
        document.dispatchEvent(event);
      }
    },

    rowClick(column_name: string, row: dynamicObj) {
      if (column_name === 'title') {
        this.$router.push('/task/' + row['id']);
        return;
      }

      if (column_name === 'document_name' && row['document_id']) {
        this.routeByStatus(row);
      }
    },
    routeByStatus(row: any, openInNewWindow = false) {
      let status = row['document_status'];

      if (status === 'validated_pending_approval') {
        this.toPendingApprovalScreen(row);
        return;
      }

      if (status === 'approved_pending_second_approval') {
        this.toPendingSecondApprovalScreen(row);
        return;
      }

      if (status === 'rejected') {
        this.toRejectedScreen(row['document_id']);
        return;
      }

      if (status === 'in_review') {
        this.toInReviewScreen(row['document_id'], row);
        return;
      }

      if (this.isStatusError(status)) {
        this.toDocumentErrorView(row);
        return;
      }

      if (!openInNewWindow) {
        this.$router.push('/field_validation_v1/' + row['document_id']);
        return;
      }

      let route = this.$router.resolve({
        path: '/field_validation_v1/' + row['document_id'],
      });
      window.open(route.href, '_blank');
    },
    isStatusError(status: string) {
      return status === 'error' || status === 'export_error';
    },

    toPendingApprovalScreen(row: any) {
      if (
        this.getSettingsByDocTypeAndSettingKey(
          row.doc_type,
          approve_before_export_v2,
        )
      ) {
        this.$router.push('/ready_for_approval_v3/' + row['document_id']);
        return;
      } else {
        this.$router.push('/ready-for-approval-v2/' + row['document_id']);
        return;
      }
    },

    toPendingSecondApprovalScreen(row: any) {
      if (
        this.getSettingsByDocTypeAndSettingKey(
          row.doc_type,
          approve_before_export_v2,
        )
      ) {
        this.$router.push(
          '/ready-for-second-approval-v3/' + row['document_id'],
        );
        return;
      } else {
        this.$router.push(
          '/ready-for-second-approval-v2/' + row['document_id'],
        );
        return;
      }
    },
    toRejectedScreen(doc_id: string) {
      this.$router.push('/rejected/' + doc_id);
    },
    toInReviewScreen(doc_id: string, row: any) {
      this.$router.push('/in_review/' + doc_id);
    },
    toDocumentErrorView(row: dynamicObj) {
      this.$router.push('/document_error/' + row['id']);
    },

    resetFilters() {
      this.resetPagination();
      this.setDefaultSettings();
      this.applyFilter();
    },

    resetAllSelectedRows() {
      this.selectionList = [];
      this.headerCheckbox = false;

      this.tasks.forEach((row: any) => {
        row['rowSelection'] = false;
      });
    },

    async deleteMultipalDocument() {
      if (!this.selectionList) {
        return;
      }
      this.processing = true;
      let response: any;
      try {
        let paramsMap = new Map();
        paramsMap.set('doc_ids', this.selectionList.join(','));
        response = await genericService.deleteRequest(
          api.delete_documents,
          paramsMap,
        );

        if (!response.success) {
          throw response;
        }

        this.headerCheckbox = false;
        this.resetAllSelectedRows();
        this.loadData();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
        const event = new CustomEvent('refresh_view', {});
        document.dispatchEvent(event);
      }
    },

    removeQuickFilter(key: string) {
      this.taskListSettingsMap.delete(key);
      this.applyFilter();
    },

    handleWebSocketResult(data: dynamicObj) {
      if (!data) {
        return;
      }
      this.use_websocket = false;
      this.updateTableData();
    },

    async getWebSocketDashboard() {
      try {
        const dashboard_filter_request = {
          type: 'dashboard',
        } as dynamicObj;

        dashboard_filter_request['data'] = {} as dynamicObj;
        let queryParams = this.queryParams;
        queryParams = queryParams.replace('?', '');
        const queryParamsAsArray = queryParams.split('&');
        queryParamsAsArray.forEach((item: any) => {
          item = item.split('=');
          if (item.length === 2) {
            dashboard_filter_request.data[item[0]] = item[1];
          }
        });
        this.data_status = 'fetching';
        const result = await this.sendMessageToSocket(
          dashboard_filter_request.type,
          dashboard_filter_request.data,
        );

        this.updateTableData();
        this.processing = false;
        return true;
      } catch (err) {
        this.handleWebsocketDelay();
      }
    },
    getListMode() {
      const list_mode: any = this.getDataByKey(CONSTANTS.tasks_list_mode);
      if (list_mode) {
        this.list_mode = list_mode;
      }
      return this.list_mode;
    },
    updateTasksList() {
      this.fetchData();
    },
    reCalulcateTotalCount() {
      // Missing/non-numeric TASK_PAGINATION_SIZE pref must not yield NaN — that
      // poisons offset (skip=NaN -> HTTP 422) and total_pages ("NaN / NaN").
      // DOCB-12859.
      this.page_size = toPositiveInt(
        this.user_settings[tasks_pagination_size],
        10,
      );
      this.setTotalPages();
    },
  },
  setup() {
    const websocket_store = useWebSocketStore();
    const { isConnected, hasError: websocketHasError } =
      storeToRefs(websocket_store);
    const {
      subscribeToChannel,
      unsubscribeToChannel,
      sendMessageByType: sendMessageToSocket,
    } = websocket_store;

    const user_store = useUserStore();
    const { sub_org_id } = storeToRefs(user_store);
    const { getSubOrgId, getOrgId } = user_store;

    const task_store = useTaskStore();
    const { loadUserAcls } = task_store;
    const {
      tasks,
      offset,
      page_size,
      list_mode,
      processing,
      statusList,
      total_pages,
      current_page,
      total_records,
      selectionList,
      headerCheckbox,
      show_table_loader,
      taskListSettingsMap,
    } = storeToRefs(task_store);
    const {
      getTasks,
      formatTaskList,
      setDefaultSettings,
      getDisplayDeadline,
      getSavedListSettings,
      getSavedFiltersAsJson,
      adjustCountForDoneTasks,
    } = task_store;

    const doc_attribute_store = useDocAttributesStore();
    const { getDocTypeAllSettings, getSettingsByDocTypeAndSettingKey } =
      doc_attribute_store;

    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { startSettingsFetch } = settings_store;

    return {
      tasks,
      offset,
      page_size,
      list_mode,
      sub_org_id,
      processing,
      statusList,
      total_pages,
      isConnected,
      current_page,
      total_records,
      selectionList,
      headerCheckbox,
      websocketHasError,
      show_table_loader,
      taskListSettingsMap,
      queryParams: ref(''),
      data_status: ref(''),
      use_websocket: ref(false),
      loading_settings,
      user_settings,
      loadUserAcls,
      getTasks,
      getOrgId,
      getSubOrgId,
      formatTaskList,
      setDefaultSettings,
      getDisplayDeadline,
      adjustCountForDoneTasks,
      subscribeToChannel,
      startSettingsFetch,
      sendMessageToSocket,
      getSavedListSettings,
      unsubscribeToChannel,
      getSavedFiltersAsJson,
      getDocTypeAllSettings,
      getSettingsByDocTypeAndSettingKey,
    };
  },
});
</script>

