<template>
  <q-select
    outlined
    dense
    class="q-mr-sm user-select"
    v-model="page_size"
    :options="pagination_options"
    @update:model-value="
      (val: any) => {
        update(val);
      }
    "
    :label="$t('pagination_size')"
  >
  </q-select>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useTaskStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  mixins: [],
  props: {},
  watch: {},

  methods: {
    update(value: string) {
      this.setPaginationSize(value);
      this.triggerApplyFilters();
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', {});
      document.dispatchEvent(event);
    },

    validatePaginationSize() {
      if (this.page_size <= 50) return;
      this.page_size = 50;
    },
  },

  mounted() {
    this.validatePaginationSize();
  },
  setup() {
    const task_store = useTaskStore();
    const { page_size } = storeToRefs(task_store);
    const { setPaginationSize } = task_store;

    return {
      setPaginationSize,
      page_size,
      pagination_options: ref(['10', '25', '50']),
    };
  },
});
</script>
<style lang="scss">
.user-select {
  width: 227px;
}
</style>
